7	
8	`timescale 1ns / 1ps
9	module fft_8(
10		input				clk,
11		input				rst,
12		input				start8,
13		input				end8,
14		input	[32-1:0]	A_real,
15		input	[32-1:0]	A_img,
16		output	[32-1:0]	out_real8,
17		output	[32-1:0]	out_img8,
18		output				start4,
19		output				end4
20	);
21	
22	/*****************<-------Control Registers and state machine------->*********************/
23		parameter			PERIOD				=	8;
24		parameter			HALT_FOR_NEXT_LAYER	=	6 + (PERIOD)/2;
25		parameter			STATE_IDLE			=	3'd0;
26		parameter			STATE_START			=	3'd1;
27		parameter			STATE_PROCESSING	=	3'd2;
28		parameter			STATE_END			=	3'd3;
29		reg		[2:0]		r_state8			=	0;
30		reg					butterfly_enable	=	0;
31		reg					S8					= 0;
32		reg		[2:0]		S8_counter			= 1;
33		reg		[4:0]		start4_counter		= 0;
34		wire	[32-1:0]	w_out_real8			;
35		wire	[32-1:0]	w_out_img8			;
36	
37	
38	
39		always@(posedge clk) begin
40			if(rst == 1)begin
41				r_state8	<=	STATE_IDLE;
42			end else begin
43				case(r_state8)
44					STATE_IDLE:begin
45						if(start8 == 1)begin
